import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"48、【井】 巽下坎上","description":"周易闡真 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"周易闡真 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"classics/chanzhen/049.md","filePath":"classics/chanzhen/049.md"}'),s={name:"classics/chanzhen/049.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：巽乎水而上水，井。井養而不窮也。改邑不改井，乃以剛中也。汔至亦未繘，井，未有功也。羸其瓶，是以兇也。</p></blockquote><h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><p>初六：井泥不食，舊井無禽。</p><p>九二：井谷射鮒，甕敝漏。</p><p>九三：井渫不食，為我心惻。可用汲，王明，並受其福。</p><p>六四：井甃，無咎。</p><p>九五：井洌，寒泉食。</p><p>上六：井收勿幕，有孚元吉。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：木上有水，井。君子以勞民勸相。</p><p>井者，取其養人也。上坎水，下巽木，是木上有水也。水升於木上，木有水而滋潤嫩脆，得其所養，井之象也。</p><p>君子有見於此，知民不可不養，既養不可不教。以是法水之流而不息，使民躬耕力作、飽食暖衣以養身；效木之叢而成林，教民知禮明義、和睦相助以養心。身心俱養，返樸歸淳，忘其勞苦，一道同風，入於不識不知、順帝之則之域矣。人之身，即國也；人之精神，即民也。整頓精神，日夜行道，即勞民也；遷善改過，去妄存誠，三家相見，四象和合，即勸相也。勞之所以忘其假，勸之所以修其真，假去真存，養之道盡矣。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>汔，音肸。繘副本，音橘。瓶，音平。谷，音育。鮒，音附。甕，烏貢反。渫，音牒。甃，音縐。冽，音列。幕，音莫。</p><p>井者，有本之水，養人不窮，取其養義。卦德上坎險，下巽入，漸進以通險，有險而能出，如木下水而出水，故謂井。此積功修德之卦，承上升卦而來。升者，巽進而順行，所以增益其道德耳。道德增益，已巽進於無險之地，根本堅固，己無險而可以濟人之險，於是積功修德，以己所養，養人之養，誠中達外，有益於彼，無傷於我，如井，改邑不改井，無喪無得，往來井井也。</p><p>夫修道者，養己已足，如井有水也。養己之後而養人，如改邑也。以自養者養人，如不改井也。養人必本於自養，養己如是，養人如是，如井無喪無得也。以養己者養人，人己皆得其所養，如往來井井也。若未到成道以後，強欲化人，則謂無本。無本之養，內無主宰，隨人使用，逐風揚塵，未益於人，先失其己，亦如井中取水，汔至於井，繘副本 猶未至，井水羸其瓶，自取其兇。蓋開導後學之事，在大道完成之後。大道完成，性命由我不由天，承先啟後，可以有益於人，無傷於我。故六爻皆以自養為主也。</p><p>初六，性質本愚，不知求人以養己，乃無而為有，亦欲效高明者以養人，如舊井有泥無水，積汙百端，禽亦不顧，焉能養人乎?此絕不知自養者也。</p><p>九二，正在養己之時，自養未足，即欲養人，無益於彼，先傷於我，如井谷外射，僅能養鮒，甕敝水漏，浸潤有限，其所以益於人者少，而其所自失者多。此養己未足者也。</p><p>九三，進於下體之上，養己已到可以養人之時，但近於險，未遇知音，限於不得養，如井水渫泛而無人食之也。然雖無人食，其道德崇高，望之者默相感化，是以為我心惻也。心惻者何?以其可用汲，望其有明眼，王公大人信而取用，則人人皆得法範，而受福無窮矣。此養己已足者也。</p><p>六四，居於險體，雖無養人之德，幸其柔而守正，能知自養，如井之凳以防險，內不傷而外不損，可無陷人之咎矣。此自知養己者也。</p><p>九五，陽居陰內，外虛內實，虛實如一，剛柔混合，大道完成，是謂有本之水，如井冽寒泉，所養深厚，取之不盡，用之不竭。此養己足而可養人者也。</p><p>上六，養己已到，如井功已收，可以勿幕井口，因人開導，自能有益於人，無傷於我。特以其吉已在於養己之初矣。此養人必本於養己者也。</p><p>然則養人之事，在成道以後，若未成道，未可養人。強欲養人，即有羸瓶之兇，養人者可不知先自養乎？</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
